._secondary:hover:not(:disabled) {
  background-color: var(--button-secondary-bg-hover);   /* #FFFFFF */
  border-color: var(--button-secondary-border-hover);   /* rgba(255, 206, 0, .6) */
  color: var(--button-primary-text-hover);              /* rgba(21, 38, 99, .8) */
}

/* CSS Modules con variables propias, sin el theme de MUI */
--button-primary-bg: var(--correo-yellow);
--button-primary-bg-hover: rgba(255, 206, 0, .6);
--field-border: var(--border-width-thin) solid var(--border-default);
--field-radius: var(--radius-xs);   /* 5px */
